settings.custom_liquid:
{%- assign p = all_products['4-week-band-strength-program'] -%}
{%- assign v = p.selected_or_first_available_variant -%}
{%- capture buy_url -%}{{ routes.root_url | append: '/' | replace: '//', '/' }}cart/{{ v.id }}:1{%- endcapture -%}
{%- capture price -%}{{ v.price | money_with_currency }}{%- endcapture -%}
{%- assign k = all_products['glute-band-kit'] -%}
{%- assign kv = k.selected_or_first_available_variant -%}
{%- capture kit_url -%}{{ k.url | default: '/products/glute-band-kit' }}{%- endcapture -%}
{%- capture kit_price -%}{{ kv.price | money_with_currency }}{%- endcapture -%}
<style>
@font-face{font-family:'MS Cinzel';font-weight:700;font-display:swap;src:url({{ 'cinzel-latin-700-normal.woff2' | asset_url }}) format('woff2')}
@font-face{font-family:'MS Cinzel';font-weight:800;font-display:swap;src:url({{ 'cinzel-latin-800-normal.woff2' | asset_url }}) format('woff2')}
@font-face{font-family:'MS Kufi';font-weight:700;font-display:swap;src:url({{ 'reem-kufi-arabic-700-normal.woff2' | asset_url }}) format('woff2')}
.ms{--void:#090806;--ink:#0F0D0A;--panel:#16130E;--panel2:#1D1912;--gold:#D9B45A;--hi:#F6DE97;--lo:#A47A2C;--pap:#EDE3CC;--muted:#A99E87;--line:rgba(217,180,90,.22);--serif:'MS Cinzel',Georgia,'Times New Roman',serif;background:var(--void);color:var(--pap);font-family:var(--font-body--family),system-ui,sans-serif;overflow-x:clip}
.ms *{box-sizing:border-box}
.ms a{color:inherit}
.ms h1,.ms h2,.ms h3{font-family:var(--serif);font-weight:700;margin:0;line-height:1.08;letter-spacing:.02em;text-transform:uppercase;color:var(--pap)}
.ms-wrap{max-width:1140px;margin:0 auto;padding:0 20px}
.ms-g{background:linear-gradient(100deg,var(--lo) 0%,var(--hi) 28%,var(--gold) 50%,var(--hi) 72%,var(--lo) 100%);background-size:220% auto;-webkit-background-clip:text;background-clip:text;color:transparent!important;animation:ms-sheen 7s linear infinite}
@keyframes ms-sheen{to{background-position:-220% center}}
.ms-eye{display:flex;align-items:center;gap:12px;font-family:var(--serif);font-size:13px;letter-spacing:.32em;text-transform:uppercase;font-weight:700;color:var(--gold);margin:0 0 18px}
.ms-eye::before{content:"";width:34px;height:1px;background:linear-gradient(90deg,transparent,var(--gold))}
.ms-center .ms-eye{justify-content:center}.ms-center .ms-eye::after{content:"";width:34px;height:1px;background:linear-gradient(90deg,var(--gold),transparent)}
.ms-ar{font-family:'MS Kufi','Geeza Pro','Noto Kufi Arabic',sans-serif;font-weight:700;letter-spacing:0}
.ms-btn{position:relative;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:56px;padding:0 30px;border-radius:2px;font-family:var(--serif);font-weight:700;font-size:15px;letter-spacing:.12em;text-transform:uppercase;text-decoration:none;transition:transform .25s ease,box-shadow .25s ease}
.ms-btn:hover{transform:translateY(-2px)}
.ms-main{background:linear-gradient(135deg,var(--hi) 0%,var(--gold) 45%,var(--lo) 100%);color:#110E08!important;box-shadow:0 14px 34px rgba(217,180,90,.25),inset 0 1px 0 rgba(255,255,255,.5)}
.ms-main:hover{box-shadow:0 18px 44px rgba(217,180,90,.4),inset 0 1px 0 rgba(255,255,255,.5)}
.ms-main::after{content:"";position:absolute;top:0;left:-60%;width:38%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.65),transparent);transform:skewX(-20deg);animation:ms-shine 4.2s ease-in-out infinite}
@keyframes ms-shine{0%,62%{left:-60%}100%{left:140%}}
.ms-ghost{border:1px solid var(--line);color:var(--pap)}
.ms-ghost:hover{border-color:var(--gold);color:var(--hi)}
.ms-arrow{transition:transform .2s}.ms-btn:hover .ms-arrow{transform:translateX(4px)}
.ms-orn{display:flex;align-items:center;justify-content:center;gap:14px;color:var(--gold);padding:0 20px}
.ms-orn::before,.ms-orn::after{content:"";height:1px;flex:1;max-width:420px;background:linear-gradient(90deg,transparent,var(--line))}
.ms-orn::after{background:linear-gradient(90deg,var(--line),transparent)}
.ms-orn i{width:9px;height:9px;transform:rotate(45deg);border:1px solid var(--gold)}
.ms-progress{position:fixed;top:0;left:0;height:2px;width:100%;background:linear-gradient(90deg,var(--lo),var(--hi));transform-origin:0 50%;transform:scaleX(0);z-index:60;pointer-events:none}
.ms-hero{position:relative;overflow:hidden;isolation:isolate;background:radial-gradient(ellipse at 70% 40%,#2a200e 0%,var(--void) 60%)}
#ms-dust{position:absolute;inset:0;width:100%;height:100%;z-index:-1;pointer-events:none}
.ms-hero .ms-wrap{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:44px;align-items:center;padding-top:88px;padding-bottom:96px}
.ms-hero h1{font-size:clamp(40px,5.6vw,74px);font-weight:800;line-height:1.02}
.ms-hero h1 .ln{display:block;overflow:hidden;padding-bottom:.08em}
.ms-hero h1 .ln > span{display:inline-block;transform:translateY(110%);animation:ms-rise 1.1s cubic-bezier(.2,.8,.2,1) forwards}
.ms-hero h1 .ln:nth-child(2) > span{animation:ms-rise 1.1s cubic-bezier(.2,.8,.2,1) .15s forwards,ms-sheen 7s linear 1.3s infinite}
@keyframes ms-rise{to{transform:none}}
.ms-fade{opacity:0;animation:ms-fadeup 1s ease forwards}
@keyframes ms-fadeup{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
.ms-lead{font-size:18px;line-height:1.65;color:var(--muted);max-width:36ch;margin:24px 0 32px}
.ms-ctas{display:flex;flex-wrap:wrap;gap:12px}
.ms-trust{display:flex;flex-wrap:wrap;gap:8px 22px;margin:24px 0 0;padding:0;list-style:none;font-size:14px;color:var(--muted)}
.ms-trust li::before{content:"✦";color:var(--gold);margin-right:8px;font-size:11px}
.ms-stats{display:flex;gap:30px;margin-top:36px;padding-top:24px;border-top:1px solid var(--line);max-width:420px}
.ms-stats div{font-size:12px;color:var(--muted);line-height:1.3;letter-spacing:.06em;text-transform:uppercase}
.ms-stats b{display:block;font-family:var(--serif);font-size:34px;font-weight:700;margin-bottom:4px}
.ms-art{position:relative;perspective:1100px}
.ms-sun{position:absolute;left:50%;top:50%;width:118%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle,rgba(246,222,151,.28) 0%,rgba(217,180,90,.12) 32%,transparent 64%);animation:ms-pulse 6s ease-in-out infinite;z-index:-1}
@keyframes ms-pulse{50%{transform:translate(-50%,-50%) scale(1.06);opacity:.8}}
.ms-ring{position:absolute;left:50%;top:50%;aspect-ratio:1;border-radius:50%;border:1px solid var(--line);transform:translate(-50%,-50%);z-index:-1;pointer-events:none}
.ms-ring.r1{width:104%;animation:ms-spin 60s linear infinite}
.ms-ring.r2{width:84%;border-style:dashed;animation:ms-spin 90s linear infinite reverse}
.ms-ring.r1::before{content:"";position:absolute;top:-4px;left:50%;width:8px;height:8px;margin-left:-4px;transform:rotate(45deg);background:var(--gold);box-shadow:0 0 14px var(--gold)}
@keyframes ms-spin{to{transform:translate(-50%,-50%) rotate(360deg)}}
.ms-art .float{animation:ms-float 7s ease-in-out infinite}
.ms-art img{display:block;width:100%;height:auto;border-radius:6px;transition:transform .25s ease-out;box-shadow:0 50px 100px rgba(0,0,0,.7),0 0 0 1px var(--line)}
@keyframes ms-float{50%{transform:translateY(-12px)}}
.ms-marquee{border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--ink);overflow:hidden;white-space:nowrap;padding:18px 0;font-family:var(--serif);font-weight:700;letter-spacing:.28em;font-size:14px;text-transform:uppercase;color:var(--gold)}
.ms-marquee div{display:inline-block;animation:ms-scroll 34s linear infinite}
.ms-marquee span{margin:0 26px}.ms-marquee i{font-style:normal;color:var(--lo)}
@keyframes ms-scroll{to{transform:translateX(-50%)}}
.ms-sec{padding:96px 0;position:relative}
.ms-sec h2{font-size:clamp(28px,3.8vw,46px);margin-bottom:16px}
.ms-sub{color:var(--muted);font-size:17px;line-height:1.7;max-width:58ch;margin:0 0 44px}
.ms-ink{background:var(--ink)}
.ms-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.ms-card{position:relative;background:linear-gradient(180deg,var(--panel2),var(--panel));border:1px solid var(--line);padding:34px 30px;overflow:hidden;transition:transform .35s ease,border-color .35s ease,box-shadow .35s ease}
.ms-card::before{content:"";position:absolute;inset:8px;border:1px solid rgba(217,180,90,.08);pointer-events:none}
.ms-card:hover{transform:translateY(-6px);border-color:rgba(217,180,90,.55);box-shadow:0 26px 50px rgba(0,0,0,.5),0 0 40px rgba(217,180,90,.08)}
.ms-card .n{font-family:var(--serif);font-size:54px;font-weight:700;line-height:1}
.ms-card h3{font-size:19px;margin:18px 0 10px;letter-spacing:.08em}
.ms-card p{margin:0;color:var(--muted);line-height:1.65;font-size:15px}
.ms-rig{position:relative;height:150px;margin:10px 0 30px;background:linear-gradient(180deg,var(--panel2),var(--panel));border:1px solid var(--line);overflow:hidden}
.ms-door{position:absolute;left:28px;top:22px;bottom:22px;width:14px;background:linear-gradient(180deg,#3a3122,#211c13);border:1px solid var(--line)}
.ms-cord{position:absolute;left:42px;top:73px;height:4px;width:30%;border-radius:4px;background:linear-gradient(90deg,var(--lo),var(--hi));box-shadow:0 0 16px rgba(217,180,90,.45);animation:ms-pull 4s cubic-bezier(.25,.1,.25,1) infinite}
.ms-handle{position:absolute;top:57px;left:calc(42px + 30%);width:20px;height:36px;border-radius:6px;border:4px solid var(--pap);animation:ms-handle 4s cubic-bezier(.25,.1,.25,1) infinite}
@keyframes ms-pull{0%{width:30%}25%{width:78%}100%{width:30%}}
@keyframes ms-handle{0%{left:calc(42px + 30%)}25%{left:calc(42px + 78%)}100%{left:calc(42px + 30%)}}
.ms-phases{display:grid;grid-template-columns:1fr 3fr;gap:12px}
.ms-ph{padding:18px 20px;background:var(--panel);border:1px solid var(--line)}
.ms-ph b{display:block;font-family:var(--serif);font-size:20px;letter-spacing:.14em;color:var(--pap)}
.ms-ph span{color:var(--muted);font-size:14px}
.ms-ph.a{animation:ms-hiA 4s infinite}.ms-ph.b{animation:ms-hiB 4s infinite}
@keyframes ms-hiA{0%,24%{border-color:var(--gold);box-shadow:0 0 24px rgba(217,180,90,.18)}26%,100%{border-color:var(--line);box-shadow:none}}
@keyframes ms-hiB{0%,24%{border-color:var(--line);box-shadow:none}26%,98%{border-color:var(--gold);box-shadow:0 0 24px rgba(217,180,90,.18)}}
.ms-plan{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);gap:52px;align-items:start}
.ms-tabs{display:inline-flex;border:1px solid var(--line);padding:4px;margin-bottom:18px}
.ms-tabs button{border:0;background:transparent;font-family:var(--serif);font-weight:700;letter-spacing:.12em;text-transform:uppercase;font-size:13px;padding:11px 18px;cursor:pointer;color:var(--muted);transition:background .25s,color .25s}
.ms-tabs button[aria-selected=true]{background:linear-gradient(135deg,var(--hi),var(--gold) 50%,var(--lo));color:#110E08}
.ms-table{border:1px solid var(--line);background:var(--panel)}
.ms-row{display:grid;grid-template-columns:38px minmax(0,1fr) auto;gap:12px;align-items:center;padding:15px 18px;border-top:1px solid var(--line);font-size:15px}
.ms-row:first-child{border-top:0}
.ms-row .i{font-family:var(--serif);font-weight:700;color:var(--gold);font-size:15px}
.ms-row .s{font-weight:700;font-variant-numeric:tabular-nums;color:var(--hi)}
.ms-panel[hidden]{display:none}
.ms-panel .ms-row{animation:ms-fadeup .45s ease both}
.ms-panel .ms-row:nth-child(2){animation-delay:.05s}.ms-panel .ms-row:nth-child(3){animation-delay:.1s}.ms-panel .ms-row:nth-child(4){animation-delay:.15s}.ms-panel .ms-row:nth-child(5){animation-delay:.2s}.ms-panel .ms-row:nth-child(6){animation-delay:.25s}
.ms-note{font-size:13px;color:var(--muted);margin:12px 2px 0}
.ms-pages{position:relative;height:520px}
.ms-pages img{position:absolute;width:62%;height:auto;border-radius:4px;box-shadow:0 30px 70px rgba(0,0,0,.6),0 0 0 1px var(--line);transition:transform .6s cubic-bezier(.2,.8,.2,1)}
.ms-pages img:nth-child(1){left:0;top:30px;transform:rotate(-5deg)}
.ms-pages img:nth-child(2){right:0;top:0;transform:rotate(4deg)}
.ms-pages:hover img:nth-child(1){transform:rotate(-8deg) translate(-14px,10px)}
.ms-pages:hover img:nth-child(2){transform:rotate(7deg) translate(14px,-6px)}
.ms-list{list-style:none;padding:0;margin:26px 0 30px}
.ms-list li{display:flex;gap:14px;padding:10px 0;font-size:16px;line-height:1.55;color:var(--pap)}
.ms-list li::before{content:"";flex:none;width:8px;height:8px;margin-top:9px;transform:rotate(45deg);background:var(--gold)}
.ms-story{text-align:center;overflow:hidden;background:radial-gradient(ellipse at 50% 30%,#241b0b 0%,var(--void) 65%)}
.ms-story .ms-wrap{position:relative}
.ms-story .ms-big{font-size:clamp(120px,22vw,260px);line-height:1.25;margin:-30px 0 0;filter:drop-shadow(0 0 30px rgba(217,180,90,.25))}
.ms-story h2{font-size:clamp(28px,3.8vw,46px);max-width:20ch;margin:0 auto 20px}
.ms-story p{color:var(--muted);font-size:17px;line-height:1.75;max-width:56ch;margin:0 auto}
.ms-story p.ms-eye{color:var(--gold);font-size:13px;line-height:1.4;max-width:none;margin:0 auto 18px}
.ms-coach{display:inline-flex;align-items:center;gap:16px;margin-top:38px;padding:14px 24px;border:1px solid var(--line);text-align:left;font-size:13px;color:var(--muted);background:rgba(22,19,14,.7)}
.ms-coach b{display:block;color:var(--pap);font-size:15px;font-family:var(--serif);letter-spacing:.06em}
.ms-coach .badge{width:46px;height:46px;border-radius:50%;display:grid;place-items:center;border:1px solid var(--gold);color:var(--gold);font-family:var(--serif);font-weight:700;font-size:12px;letter-spacing:.06em;flex:none}
.ms-faq{max-width:800px}
.ms-faq details{border-bottom:1px solid var(--line);padding:22px 0}
.ms-faq summary{cursor:pointer;font-weight:600;font-size:17px;list-style:none;display:flex;justify-content:space-between;gap:16px;color:var(--pap)}
.ms-faq summary::-webkit-details-marker{display:none}
.ms-faq summary::after{content:"+";color:var(--gold);font-size:24px;line-height:1;transition:transform .3s}
.ms-faq details[open] summary::after{transform:rotate(45deg)}
.ms-faq p{margin:12px 0 0;color:var(--muted);line-height:1.7;animation:ms-fadeup .35s ease}
.ms-final{text-align:center;background:radial-gradient(ellipse at 50% 110%,rgba(217,180,90,.22),transparent 60%),var(--void)}
.ms-final h2{font-size:clamp(32px,5vw,60px)}
.ms-fine{font-size:12px;color:var(--muted);text-align:center;margin:0;padding:22px 20px 44px;background:var(--void);letter-spacing:.04em}
.ms-sticky{position:fixed;left:12px;right:12px;bottom:12px;z-index:55;display:none;align-items:center;justify-content:space-between;gap:12px;padding:10px 10px 10px 18px;background:rgba(15,13,10,.94);border:1px solid var(--line);color:var(--pap);box-shadow:0 18px 40px rgba(0,0,0,.5);transform:translateY(160%);transition:transform .35s cubic-bezier(.2,.8,.2,1);backdrop-filter:blur(8px)}
.ms-sticky.on{transform:none}
.ms-sticky b{font-size:13px;display:block;font-family:var(--serif);letter-spacing:.06em}.ms-sticky span{font-size:12px;color:var(--muted)}
.ms-sticky .ms-btn{min-height:44px;padding:0 18px;font-size:13px}
.ms-r{opacity:0;transform:translateY(34px);transition:opacity .9s ease,transform .9s cubic-bezier(.2,.8,.2,1)}
.ms-r.in{opacity:1;transform:none}
.ms-d1{transition-delay:.12s}.ms-d2{transition-delay:.24s}.ms-d3{transition-delay:.36s}
@media (max-width:849px){
  .ms-hero .ms-wrap,.ms-plan{grid-template-columns:minmax(0,1fr);gap:40px}
  .ms-hero .ms-wrap{padding-top:52px;padding-bottom:76px}
  .ms-cards{grid-template-columns:minmax(0,1fr)}
  .ms-sec{padding:68px 0}
  .ms-ctas .ms-btn{width:100%}
  .ms-pages{height:360px}
  .ms-phases{grid-template-columns:1fr 1.6fr}
  .ms-sticky{display:flex}
  .ms-stats{gap:22px}
  .ms-eye{letter-spacing:.22em}
}
@media (prefers-reduced-motion:reduce){
  .ms *,.ms *::before,.ms *::after{animation:none!important;transition:none!important}
  .ms-hero h1 .ln > span{transform:none}.ms-fade{opacity:1}.ms-r{opacity:1;transform:none}
}
</style>

<div class="ms" id="ms">
  <div class="ms-progress" id="ms-progress"></div>

  <section class="ms-hero">
    <canvas id="ms-dust" aria-hidden="true"></canvas>
    <div class="ms-wrap">
      <div>
        <p class="ms-eye ms-fade" style="animation-delay:.05s">Masir · <span class="ms-ar" style="font-size:16px">مصير</span></p>
        <h1><span class="ln"><span>Stronger glutes,</span></span> <span class="ln"><span class="ms-g">coached.</span></span></h1>
        <p class="ms-lead ms-fade" style="animation-delay:.4s">Four loop bands and a coach's 4-week plan to use them. Three 30-minute sessions a week at home, written by a certified strength coach.</p>
        <div class="ms-ctas ms-fade" style="animation-delay:.55s">
          <a class="ms-btn ms-main" href="{{ kit_url }}">Get the kit · {{ kit_price }} <span class="ms-arrow">→</span></a>
          <a class="ms-btn ms-ghost" href="#ms-plan">See Day A</a>
        </div>
        <ul class="ms-trust ms-fade" style="animation-delay:.7s"><li>Free US shipping · 7-14 business days</li><li>Program PDF emailed with your order</li><li>30-day returns</li></ul>
        <div class="ms-stats ms-fade" style="animation-delay:.85s">
          <div><b class="ms-g" data-count="4">4</b>bands</div><div><b class="ms-g" data-count="4">4</b>weeks</div><div><b class="ms-g" data-count="30">30</b>minutes a session</div>
        </div>
      </div>
      <div class="ms-art ms-fade" style="animation-delay:.3s">
        <div class="ms-sun"></div><div class="ms-ring r1"></div><div class="ms-ring r2"></div>
        <div class="float">
          {%- assign hero = k.images[1] | default: p.featured_image -%}
          {%- if hero -%}
            {{ hero | image_url: width: 1000 | image_tag: loading: 'eager', fetchpriority: 'high', id: 'ms-tilt', alt: 'The Masir Glute Band Kit: 4 loop bands and the 4-Week Glute Band Program', sizes: '(min-width: 850px) 50vw, 100vw' }}
          {%- endif -%}
        </div>
      </div>
    </div>
  </section>

  <div class="ms-marquee" aria-hidden="true"><div>{%- for i in (1..2) -%}<span>4 bands</span><i>✦</i><span>4 weeks</span><i>✦</i><span>30 minutes</span><i>✦</i><span>3× a week</span><i>✦</i><span>Coached, not random</span><i>✦</i><span>Free US shipping</span><i>✦</i>{%- endfor -%}</div></div>

  <section class="ms-sec ms-ink">
    <div class="ms-wrap">
      <p class="ms-eye ms-r">How it works</p>
      <h2 class="ms-r ms-d1">A plan, not a playlist.</h2>
      <p class="ms-sub ms-r ms-d2">Most glute workouts are a random list of exercises. This one tells you what to do each day, which band to use, and when to move up.</p>
      <div class="ms-cards">
        <div class="ms-card ms-r"><div class="n ms-g">I</div><h3>Learn the moves</h3><p>Weeks 1-2 teach the squat, bridge, side walk and hip moves with a lighter band.</p></div>
        <div class="ms-card ms-r ms-d1"><div class="n ms-g">II</div><h3>Add load</h3><p>Weeks 3-4 move you up a band, add a set and a pause at the top, so your glutes keep getting stronger instead of just tired.</p></div>
        <div class="ms-card ms-r ms-d2"><div class="n ms-g">III</div><h3>Prove it</h3><p>Test your squats and single-leg bridges on day 1 and again in week 4, and log your band and reps every week.</p></div>
      </div>
    </div>
  </section>

  <div class="ms-orn" aria-hidden="true"><i></i></div>

  <section class="ms-sec">
    <div class="ms-wrap">
      <p class="ms-eye ms-r">The one rule</p>
      <h2 class="ms-r ms-d1">The slow way back is the workout.</h2>
      <p class="ms-sub ms-r ms-d2">Bands are easy to do badly: people rush the rep and let the band pull them back. Every exercise in the plan uses one tempo.</p>
      <div class="ms-phases ms-r ms-d1"><div class="ms-ph a"><b>PULL</b><span>1 second</span></div><div class="ms-ph b"><b>RETURN</b><span>2-3 seconds, under control</span></div></div>
    </div>
  </section>

  <section class="ms-sec ms-ink" id="ms-plan">
    <div class="ms-wrap ms-plan">
      <div>
        <p class="ms-eye ms-r">Inside the plan</p>
        <h2 class="ms-r ms-d1">Here's Day A.</h2>
        <p class="ms-sub ms-r ms-d2" style="margin-bottom:26px">The full program has Day A and Day B, a warm-up, coaching cues for every exercise, a finisher and your progress log.</p>
        <div class="ms-r ms-d2">
