<script>
(function(){
  var root=document.getElementById('ms'); if(!root) return;
  var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var els=root.querySelectorAll('.ms-r');
  if('IntersectionObserver' in window && !reduce){
    var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}})},{threshold:.15,rootMargin:'0px 0px -40px 0px'});
    els.forEach(function(el){io.observe(el)});
  } else { els.forEach(function(el){el.classList.add('in')}); }
  var bar=document.getElementById('ms-progress'), sticky=document.getElementById('ms-sticky'), hero=root.querySelector('.ms-hero');
  function onScroll(){
    var h=document.documentElement, max=h.scrollHeight-h.clientHeight;
    if(bar) bar.style.transform='scaleX('+(max>0?h.scrollTop/max:0)+')';
    if(sticky&&hero){var r=hero.getBoundingClientRect(); sticky.classList.toggle('on', r.bottom<0 && h.scrollTop<max-260);}
  }
  window.addEventListener('scroll',onScroll,{passive:true}); onScroll();
  var tabs=root.querySelectorAll('[data-tab]');
  tabs.forEach(function(t){t.addEventListener('click',function(){
    tabs.forEach(function(x){x.setAttribute('aria-selected', x===t?'true':'false')});
    root.querySelectorAll('[data-panel]').forEach(function(pn){pn.hidden = pn.getAttribute('data-panel')!==t.getAttribute('data-tab')});
  })});
  var img=document.getElementById('ms-tilt');
  if(img && !reduce && window.matchMedia('(hover:hover)').matches){
    var art=img.closest('.ms-art');
    art.addEventListener('mousemove',function(e){var b=art.getBoundingClientRect();var x=(e.clientX-b.left)/b.width-.5,y=(e.clientY-b.top)/b.height-.5;img.style.transform='rotateY('+(x*10)+'deg) rotateX('+(-y*10)+'deg)';});
    art.addEventListener('mouseleave',function(){img.style.transform='';});
  }
  if(!reduce){root.querySelectorAll('[data-count]').forEach(function(el){var n=+el.getAttribute('data-count'),s=null;el.textContent='0';function step(ts){if(!s)s=ts;var p=Math.min((ts-s)/1400,1);el.textContent=Math.round(n*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(step);}setTimeout(function(){requestAnimationFrame(step)},1000);});}
  var cv=document.getElementById('ms-dust');
  if(cv && !reduce){
    var ctx=cv.getContext('2d'), dpr=Math.min(window.devicePixelRatio||1,2), W=0,H=0, parts=[], run=true;
    function size(){W=cv.offsetWidth;H=cv.offsetHeight;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
    size(); window.addEventListener('resize',size);
    var n=W<700?34:70;
    for(var i=0;i<n;i++)parts.push({x:Math.random()*W,y:Math.random()*H,r:Math.random()*1.6+.4,v:Math.random()*.35+.08,a:Math.random()*.6+.2,t:Math.random()*6.28});
    if('IntersectionObserver' in window){new IntersectionObserver(function(es){var was=run;run=es[0].isIntersecting;if(run&&!was)requestAnimationFrame(tick)}).observe(cv);}
    function tick(){
      if(!run)return; ctx.clearRect(0,0,W,H);
      for(var i=0;i<parts.length;i++){var p=parts[i];p.y-=p.v;p.t+=.02;p.x+=Math.sin(p.t)*.2;if(p.y<-6){p.y=H+6;p.x=Math.random()*W;}
        var al=p.a*(.6+.4*Math.sin(p.t*1.7));ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,6.283);ctx.fillStyle='rgba(240,205,120,'+al+')';ctx.shadowColor='rgba(240,205,120,.9)';ctx.shadowBlur=6;ctx.fill();}
      requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }
})();
</script>
